import anyio
from mcp.server import Server, ServerRequestContext
from mcp.server.stdio import stdio_server
from mcp.types import CallToolRequestParams, CallToolResult, ImageContent, ListToolsResult, TextContent, Tool

TOOLS = [Tool(name=n, input_schema={"type": "object"}) for n in ("text", "structured", "fail", "zero")]


async def list_tools(ctx, params):
    return ListToolsResult(tools=TOOLS)


async def call_tool(ctx: ServerRequestContext, params: CallToolRequestParams) -> CallToolResult:
    img = ImageContent(type="image", data="aGk=", mime_type="image/png")
    if params.name == "text":
        return CallToolResult(content=[TextContent(type="text", text="a"), img, TextContent(type="text", text="b")])
    if params.name == "structured":
        return CallToolResult(
            content=[TextContent(type="text", text="ignored")], structured_content={"ok": True, "args": params.arguments}
        )
    if params.name == "zero":
        return CallToolResult(content=[TextContent(type="text", text="ignored")], structured_content=0)
    return CallToolResult(
        content=[TextContent(type="text", text="no such"), img, TextContent(type="text", text="version")], is_error=True
    )


server = Server("t", on_list_tools=list_tools, on_call_tool=call_tool)


async def main():
    async with stdio_server() as (r, w):
        await server.run(r, w, server.create_initialization_options())


anyio.run(main)

